    Bug 1960682 - nsIMsgCopyService.getArrivedFolder should take nsIMsgFolder parameter instead of using nsISupports unnecessarily. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D245901

diff --git a/mailnews/base/public/nsIMsgCopyService.idl b/mailnews/base/public/nsIMsgCopyService.idl
index ad76b1eebfd..bbca49d248a 100644
--- a/mailnews/base/public/nsIMsgCopyService.idl
+++ b/mailnews/base/public/nsIMsgCopyService.idl
@@ -121,8 +121,8 @@ interface nsIMsgCopyService : nsISupports {
    * Get the actual folder resulting from moving/copying a folder. This can be
    * used in onStopCopy.
    *
-   * @param aSupport   The originator of CopyFolder
+   * @param aSrcFolder The originator of CopyFolder
    * @return           The folder as the result of a move/copy operation
    */
-  nsIMsgFolder getArrivedFolder(in nsISupports aSupport);
+  nsIMsgFolder getArrivedFolder(in nsIMsgFolder aSrcFolder);
 };
diff --git a/mailnews/base/src/nsMsgCopyService.cpp b/mailnews/base/src/nsMsgCopyService.cpp
index 6e8c2ba411e..7443ad9a463 100644
--- a/mailnews/base/src/nsMsgCopyService.cpp
+++ b/mailnews/base/src/nsMsgCopyService.cpp
@@ -578,11 +578,11 @@ nsMsgCopyService::NotifyCompletion(nsISupports* aSupport,
 }

 NS_IMETHODIMP
-nsMsgCopyService::GetArrivedFolder(nsISupports* aSupport,
+nsMsgCopyService::GetArrivedFolder(nsIMsgFolder* aSrcFolder,
                                    nsIMsgFolder** aArrFolder) {
   NS_ENSURE_ARG_POINTER(aArrFolder);
   for (auto copyRequest : m_copyRequests) {
-    if (SameCOMIdentity(copyRequest->m_srcSupport, aSupport) &&
+    if (SameCOMIdentity(copyRequest->m_srcSupport, aSrcFolder) &&
         copyRequest->m_processed) {
       NS_IF_ADDREF(*aArrFolder = copyRequest->m_arrFolder);
       return NS_OK;
